parameters.jsCode:
const normalizarTexto = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const texto =
  normalizarTexto($json.message);

// --------------------------------------------------
// Intenciones explícitas para iniciar una agenda
// --------------------------------------------------

const patronesAgenda = [
  /\bagendar\b/,
  /\breservar\b/,
  /\bpedir\s+(una\s+)?hora\b/,
  /\btomar\s+(una\s+)?hora\b/,
  /\bsacar\s+(una\s+)?hora\b/,
  /\bnecesito\s+(una\s+)?hora\b/,
  /\bquiero\s+(una\s+)?hora\b/,
  /\bquiero\s+(una\s+)?cita\b/,
  /\bnecesito\s+(una\s+)?cita\b/,
  /\bconsulta\s+general\s+para\b/,
  /\bagenda\s+medica\b/,
  /\bcita\s+veterinaria\b/,
  /\b(?:quiero|necesito|solicito)\s+(?:una\s+)?consulta(?:\s+veterinaria)?\b/
];

// --------------------------------------------------
// Comandos para detener una agenda abierta
// --------------------------------------------------

const patronesCancelarAgenda = [
  /\bcancelar\s+(?:la\s+)?agenda\b/,
  /\bcancelar\s+(?:la\s+)?solicitud\b/,
  /\bcancelar\s+(?:esta\s+)?solicitud\b/,
  /\bcancelar\s+(?:el\s+)?proceso\s+de\s+agenda\b/,
  /\bdejar\s+sin\s+efecto\s+(?:la\s+)?solicitud\b/,
  /\bsalir\s+de\s+(?:la\s+)?agenda\b/,
  /\babandonar\s+(?:la\s+)?agenda\b/,
  /\bdetener\s+(?:la\s+)?solicitud\s+de\s+agenda\b/,
  /\bno\s+quiero\s+seguir\s+agendando\b/,
  /\bno\s+quiero\s+continuar\s+con\s+(?:la\s+)?solicitud\b/
];

// --------------------------------------------------
// Comandos para limpiar y comenzar nuevamente
// --------------------------------------------------

const patronesReiniciarAgenda = [
  /\bempezar\s+de\s+nuevo\b/,
  /\bcomenzar\s+de\s+nuevo\b/,
  /\breiniciar\s+(?:la\s+)?agenda\b/,
  /\breiniciar\s+(?:la\s+)?reserva\b/,
  /\bnueva\s+solicitud\s+de\s+agenda\b/
];

const solicitaCancelarAgenda =
  patronesCancelarAgenda.some(
    (patron) =>
      patron.test(texto)
  );

const solicitaReiniciarAgenda =
  patronesReiniciarAgenda.some(
    (patron) =>
      patron.test(texto)
  );

const solicitaControlAgenda =
  solicitaCancelarAgenda ||
  solicitaReiniciarAgenda;

const accionControlAgenda =
  solicitaCancelarAgenda
    ? "cancelar"
    : solicitaReiniciarAgenda
      ? "reiniciar"
      : "";

// --------------------------------------------------
// Señales de continuación de una agenda abierta
// --------------------------------------------------

const patronesContinuacionAgenda = [
  // Selección de alternativa
  /^[1-9]\s*[.)]?$/,
  /\b(?:opcion|alternativa)\s*(?:numero\s*)?[1-9]\b/,
  /\b(?:elijo|escojo|prefiero|selecciono|quiero)\s+(?:la\s+)?(?:opcion\s+)?(?:primera|segunda|tercera|[1-9])\b/,

  // Fechas relativas o días de la semana
  /\b(?:hoy|manana|pasado\s+manana)\b/,
  /\b(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b/,

  // Fechas explícitas
  /\b\d{1,2}\s+de\s+[a-z]+(?:\s+de\s+\d{4})?\b/,

  // Horas
  /\b(?:a|para)\s+las?\s+\d{1,2}(?::\d{2}|\s+y\s+(?:media|cuarto|\d{1,2}))?(?:\s+de\s+la\s+(?:manana|tarde|noche))?\b/,
  /\b\d{1,2}:\d{2}\b/,

  // Confirmación de horario
  /\b(?:confirmo|confirmar|de\s+acuerdo|esa\s+hora|ese\s+horario|me\s+sirve|esta\s+bien)\b/,

  // Datos del tutor o la mascota
  /\b(?:mi\s+nombre|soy|tutor|mascota|telefono|celular|contacto)\b/,

  // Número móvil o teléfono escrito directamente
  /\b(?:\+?56\s*)?9(?:[\s.-]*\d){8}\b/
];

const continuaAgendaPorContenido =
  patronesContinuacionAgenda.some(
    (patron) =>
      patron.test(texto)
  );

// --------------------------------------------------
// Señales de consulta pública informativa
// --------------------------------------------------

const patronesConsultaInformativa = [
  /\b(?:cuanto\s+cuesta|cuanto\s+sale|cual\s+es\s+el\s+precio|precio|valor)\b/,
  /\b(?:horario\s+de\s+atencion|a\s+que\s+hora\s+abren|a\s+que\s+hora\s+cierran)\b/,
  /\b(?:donde\s+estan|donde\s+queda|donde\s+se\s+ubica|ubicacion|direccion)\b/,
  /\b(?:que\s+servicios|cuales\s+servicios|que\s+ofrecen|que\s+tienen)\b/,
  /\b(?:medios?\s+de\s+pago|formas?\s+de\s+pago|aceptan\s+tarjeta|aceptan\s+transferencia)\b/,
  /\b(?:quiero\s+saber|necesito\s+saber|quisiera\s+saber|informame|cuentame)\b/
];

const parecePregunta =
  /[¿?]/.test(String($json.message || "")) ||
  /^(?:que|cual|cuales|cuanto|cuantos|como|donde|cuando|por\s+que|tienen|ofrecen|aceptan|atienden|venden|hay)\b/.test(
    texto
  );

const iniciaSolicitudAgenda =
  patronesAgenda.some(
    (patron) =>
      patron.test(texto)
  );

const esConsultaInformativa =
  !solicitaControlAgenda &&
  !iniciaSolicitudAgenda &&
  !continuaAgendaPorContenido &&
  (
    parecePregunta ||
    patronesConsultaInformativa.some(
      (patron) =>
        patron.test(texto)
    )
  );

// --------------------------------------------------
// Estado conversacional existente
// --------------------------------------------------

const estadoActual =
  String(
    $json.estadoAgenda?.estado_agenda || ""
  )
    .trim()
    .toLowerCase();

const estadosFinalizados = [
  "confirmada",
  "cancelada",
  "cerrada"
];

const vieneDeAgendaFinalizada =
  $json.iniciarNuevaAgenda === true;

const teniaAgendaAbierta =
  Boolean($json.existeEstado) &&
  !vieneDeAgendaFinalizada &&
  !estadosFinalizados.includes(
    estadoActual
  );

const tieneAgendaEnCurso =
  teniaAgendaAbierta &&
  !solicitaControlAgenda &&
  !esConsultaInformativa;

// --------------------------------------------------
// Resultado
// --------------------------------------------------

return {
  json: {
    ...$json,

    textoNormalizado:
      texto,

    solicitaCancelarAgenda,
    solicitaReiniciarAgenda,
    solicitaControlAgenda,
    accionControlAgenda,

    teniaAgendaAbierta,
    continuaAgendaPorContenido,
    esConsultaInformativa,
    tieneAgendaEnCurso,

    esSolicitudAgendaMedica:
      iniciaSolicitudAgenda ||
      tieneAgendaEnCurso
  }
};

const normalizar = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const mensaje = normalizar($json.message);
const config = $json.agendaConfig || {};
const estadoPrevio = $json.estadoAgenda || {};

const fechaPendientePrevia =
  String(
    estadoPrevio.fecha_pendiente || ""
  ).trim();

const horaPendientePrevia =
  String(
    estadoPrevio.hora_pendiente || ""
  ).trim();

const zonaHoraria =
  config.zona_horaria || "America/Santiago";

const duracionMinutos =
  Number(config.duracion_minutos) || 30;

const cantidadAlternativas =
  Number(config.cantidad_alternativas) || 3;

const DateTime =
  $now.constructor;

const ahora =
  $now.setZone(zonaHoraria);

// --------------------------------------------------
// Utilidades para datos parciales guardados
// --------------------------------------------------

const validarFechaPendiente = (valor) => {
  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(valor)
  ) {
    return "";
  }

  const fechaValidada =
    DateTime.fromISO(
      valor,
      {
        zone: zonaHoraria
      }
    );

  if (
    !fechaValidada.isValid ||
    fechaValidada.toISODate() !== valor
  ) {
    return "";
  }

  return valor;
};

const validarHoraPendiente = (valor) => {
  if (
    !/^([01]\d|2[0-3]):[0-5]\d$/.test(valor)
  ) {
    return "";
  }

  return valor;
};

const formatearHora = (
  hora,
  minuto
) =>
  `${String(hora).padStart(2, "0")}:` +
  `${String(minuto).padStart(2, "0")}`;

// --------------------------------------------------
// Alternativas guardadas
// --------------------------------------------------

const obtenerOpcionesGuardadas = () => {
  const valor =
    estadoPrevio.opciones_json;

  if (Array.isArray(valor)) {
    return valor;
  }

  try {
    const resultado =
      JSON.parse(valor || "[]");

    if (Array.isArray(resultado)) {
      return resultado;
    }

    if (
      Array.isArray(
        resultado?.opcionesAgenda
      )
    ) {
      return resultado.opcionesAgenda;
    }
  } catch (error) {}

  return [];
};

const opcionesGuardadas =
  obtenerOpcionesGuardadas();

const detectarOpcionSeleccionada = () => {
  const limite =
    Math.max(
      cantidadAlternativas,
      1
    );

  const numeroDirecto =
    mensaje.match(
      new RegExp(
        `^([1-${limite}])\\s*[.)]?$`
      )
    );

  if (numeroDirecto) {
    return Number(
      numeroDirecto[1]
    );
  }

  const numeroEnFrase =
    mensaje.match(
      new RegExp(
        `\\b(?:opcion|alternativa|elijo|escojo|prefiero|selecciono|quiero)` +
        `(?:\\s+la)?(?:\\s+opcion)?\\s+([1-${limite}])\\b`
      )
    );

  if (numeroEnFrase) {
    return Number(
      numeroEnFrase[1]
    );
  }

  const equivalencias = {
    primera: 1,
    segunda: 2,
    tercera: 3,
    uno: 1,
    dos: 2,
    tres: 3
  };

  for (
    const [palabra, numero]
    of Object.entries(
      equivalencias
    )
  ) {
    if (
      numero <= limite &&
      new RegExp(
        `\\b${palabra}\\b`
      ).test(mensaje)
    ) {
      return numero;
    }
  }

  return null;
};

const opcionSeleccionada =
  detectarOpcionSeleccionada();

if (opcionSeleccionada) {
  const opcion =
    opcionesGuardadas.find(
      (item, indice) =>
        Number(item.numero) ===
          opcionSeleccionada ||
        indice + 1 ===
          opcionSeleccionada
    );

  const inicioOpcion =
    opcion?.inicio ||
    opcion?.startTime ||
    "";

  if (inicioOpcion) {
    const inicio =
      DateTime.fromISO(
        inicioOpcion,
        {
          zone: zonaHoraria
        }
      );

    if (inicio.isValid) {
      const finOpcionTexto =
        opcion?.fin ||
        opcion?.endTime ||
        "";

      const finOpcion =
        finOpcionTexto
          ? DateTime.fromISO(
              finOpcionTexto,
              {
                zone: zonaHoraria
              }
            )
          : null;

      const fin =
        finOpcion?.isValid
          ? finOpcion
          : inicio.plus({
              minutes:
                duracionMinutos
            });

      return {
        json: {
          ...$json,

          estadoAgenda: {
            ...estadoPrevio,

            start_time:
              inicio.toISO(),

            fecha_pendiente:
              inicio.toISODate(),

            hora_pendiente:
              inicio.toFormat(
                "HH:mm"
              )
          },

          startTime:
            inicio.toISO(),

          endTime:
            fin.toISO(),

          interpretacionAgenda: {
            origen:
              "opcion_guardada",

            opcion_seleccionada:
              opcionSeleccionada,

            fecha_detectada:
              inicio.toISODate(),

            hora_detectada:
              inicio.toFormat(
                "HH:mm"
              ),

            tiene_fecha_hora:
              true,

            fecha_hora_pasada:
              inicio <= ahora
          }
        }
      };
    }
  }
}

// --------------------------------------------------
// Interpretación de fecha
// --------------------------------------------------

const meses = {
  enero: 1,
  febrero: 2,
  marzo: 3,
  abril: 4,
  mayo: 5,
  junio: 6,
  julio: 7,
  agosto: 8,
  septiembre: 9,
  setiembre: 9,
  octubre: 10,
  noviembre: 11,
  diciembre: 12
};

const diasSemana = {
  domingo: 7,
  lunes: 1,
  martes: 2,
  miercoles: 3,
  jueves: 4,
  viernes: 5,
  sabado: 6
};

let fecha = null;

const fechaExplicita =
  mensaje.match(
    /\b(\d{1,2})\s+de\s+([a-z]+)(?:\s+de\s+(\d{4}))?\b/
  );

if (fechaExplicita) {
  const dia =
    Number(
      fechaExplicita[1]
    );

  const mes =
    meses[
      fechaExplicita[2]
    ];

  const anio =
    fechaExplicita[3]
      ? Number(
          fechaExplicita[3]
        )
      : ahora.year;

  if (mes) {
    const fechaCandidata =
      ahora.set({
        year: anio,
        month: mes,
        day: dia,
        hour: 0,
        minute: 0,
        second: 0,
        millisecond: 0
      });

    if (
      fechaCandidata.isValid &&
      fechaCandidata.year === anio &&
      fechaCandidata.month === mes &&
      fechaCandidata.day === dia
    ) {
      fecha =
        fechaCandidata;
    }
  }
} else if (
  /\bpasado\s+manana\b/.test(
    mensaje
  )
) {
  fecha =
    ahora.plus({
      days: 2
    });
} else if (
  /\bmanana\b/.test(
    mensaje
  )
) {
  fecha =
    ahora.plus({
      days: 1
    });
} else if (
  /\bhoy\b/.test(
    mensaje
  )
) {
  fecha =
    ahora;
} else {
  for (
    const [nombreDia, numeroDia]
    of Object.entries(
      diasSemana
    )
  ) {
    if (
      new RegExp(
        `\\b${nombreDia}\\b`
      ).test(mensaje)
    ) {
      let diasHastaFecha =
        (
          numeroDia -
          ahora.weekday +
          7
        ) % 7;

      if (
        diasHastaFecha === 0 &&
        /\bproximo\b/.test(
          mensaje
        )
      ) {
        diasHastaFecha = 7;
      }

      fecha =
        ahora.plus({
          days:
            diasHastaFecha
        });

      break;
    }
  }
}

// --------------------------------------------------
// Interpretación de hora
// --------------------------------------------------

const horaConPalabras =
  mensaje.match(
    /\b(?:a\s+las?|para\s+las?)\s+(\d{1,2})(?:(?::(\d{2}))|\s+y\s+(media|cuarto|\d{1,2}))?\s*(?:de\s+la\s+)?(manana|tarde|noche)?\b/
  );

const horaConDosPuntos =
  mensaje.match(
    /\b(\d{1,2}):(\d{2})\b/
  );

let hora = null;
let minuto = null;
let periodo = "";

if (horaConPalabras) {
  hora =
    Number(
      horaConPalabras[1]
    );

  if (
    horaConPalabras[2]
  ) {
    minuto =
      Number(
        horaConPalabras[2]
      );
  } else if (
    horaConPalabras[3] ===
      "media"
  ) {
    minuto = 30;
  } else if (
    horaConPalabras[3] ===
      "cuarto"
  ) {
    minuto = 15;
  } else if (
    horaConPalabras[3]
  ) {
    minuto =
      Number(
        horaConPalabras[3]
      );
  } else {
    minuto = 0;
  }

  periodo =
    horaConPalabras[4] ||
    "";
} else if (
  horaConDosPuntos
) {
  hora =
    Number(
      horaConDosPuntos[1]
    );

  minuto =
    Number(
      horaConDosPuntos[2]
    );
}

if (
  hora !== null &&
  minuto !== null
) {
  if (
    (
      periodo === "tarde" ||
      periodo === "noche"
    ) &&
    hora < 12
  ) {
    hora += 12;
  }

  if (
    periodo === "manana" &&
    hora === 12
  ) {
    hora = 0;
  }

  if (
    !periodo &&
    hora >= 1 &&
    hora <= 6
  ) {
    hora += 12;
  }

  if (
    hora < 0 ||
    hora > 23 ||
    minuto < 0 ||
    minuto > 59
  ) {
    hora = null;
    minuto = null;
  }
}

// --------------------------------------------------
// Recuperación de fecha y hora anteriores
// --------------------------------------------------

const inicioPrevio =
  estadoPrevio.start_time
    ? DateTime.fromISO(
        estadoPrevio.start_time,
        {
          zone:
            zonaHoraria
        }
      )
    : null;

const inicioPrevioValido =
  Boolean(
    inicioPrevio?.isValid
  );

const fechaDetectadaActual =
  Boolean(
    fecha?.isValid
  );

const horaDetectadaActual =
  hora !== null &&
  minuto !== null;

let fechaPendiente =
  fechaDetectadaActual
    ? fecha.toISODate()
    : validarFechaPendiente(
        fechaPendientePrevia
      );

if (
  !fechaPendiente &&
  inicioPrevioValido
) {
  fechaPendiente =
    inicioPrevio.toISODate();
}

let horaPendiente =
  horaDetectadaActual
    ? formatearHora(
        hora,
        minuto
      )
    : validarHoraPendiente(
        horaPendientePrevia
      );

if (
  !horaPendiente &&
  inicioPrevioValido
) {
  horaPendiente =
    inicioPrevio.toFormat(
      "HH:mm"
    );
}

// --------------------------------------------------
// Construcción del resultado final
// --------------------------------------------------

let startTime = "";
let endTime = "";

let origen =
  "sin_fecha_hora";

if (
  fechaPendiente &&
  horaPendiente
) {
  const inicio =
    DateTime.fromISO(
      `${fechaPendiente}T${horaPendiente}:00`,
      {
        zone:
          zonaHoraria
      }
    );

  if (inicio.isValid) {
    startTime =
      inicio.toISO();

    endTime =
      inicio
        .plus({
          minutes:
            duracionMinutos
        })
        .toISO();

    if (
      fechaDetectadaActual &&
      horaDetectadaActual
    ) {
      origen =
        "mensaje_actual";
    } else if (
      fechaDetectadaActual
    ) {
      origen =
        "fecha_actual_hora_guardada";
    } else if (
      horaDetectadaActual
    ) {
      origen =
        "fecha_guardada_hora_actual";
    } else {
      origen =
        "estado_guardado";
    }
  }
}

if (
  !startTime &&
  (
    fechaPendiente ||
    horaPendiente
  )
) {
  origen =
    "datos_parciales";
}

const inicioFinal =
  startTime
    ? DateTime.fromISO(
        startTime,
        {
          zone:
            zonaHoraria
        }
      )
    : null;

return {
  json: {
    ...$json,

    estadoAgenda: {
      ...estadoPrevio,

      start_time:
        startTime,

      fecha_pendiente:
        fechaPendiente,

      hora_pendiente:
        horaPendiente
    },

    startTime,
    endTime,

    interpretacionAgenda: {
      origen,

      opcion_seleccionada:
        null,

      fecha_detectada:
        fechaPendiente,

      hora_detectada:
        horaPendiente,

      tiene_fecha_hora:
        Boolean(
          startTime &&
          endTime
        ),

      fecha_hora_pasada:
        Boolean(
          inicioFinal?.isValid &&
          inicioFinal <= ahora
        )
    }
  }
};

const solicitud =
  $("Interpretar fecha y hora agenda").first().json;

return {
  json: {
    ...solicitud,
    disponibilidad: {
      available: $json.available === true
    }
  }
};

parameters.timeMin:
={{
(() => {
  const tz =
    $json.agendaConfig?.zona_horaria ||
    "America/Santiago";

  let fechaBase =
    $json.interpretacionAgenda?.fecha_detectada ||
    "";

  if (
    !fechaBase &&
    $json.estadoAgenda?.start_time
  ) {
    fechaBase = DateTime.fromISO(
      $json.estadoAgenda.start_time
    )
      .setZone(tz)
      .toISODate();
  }

  if (!fechaBase) {
    try {
      const opciones = JSON.parse(
        $json.estadoAgenda?.opciones_json ||
        "[]"
      );

      const primera =
        Array.isArray(opciones)
          ? opciones[0]
          : null;

      fechaBase =
        primera?.fecha ||
        String(
          primera?.inicio || ""
        ).slice(0, 10);
    } catch {}
  }

  fechaBase =
    fechaBase ||
    $now.setZone(tz).toISODate();

  return DateTime.fromISO(
    fechaBase,
    { zone: tz }
  )
    .startOf("day")
    .toISO();
})()
}}

parameters.timeMax:
={{
(() => {
  const tz =
    $json.agendaConfig?.zona_horaria ||
    "America/Santiago";

  const dias =
    Number(
      $json.agendaConfig?.dias_a_buscar
    ) || 7;

  let fechaBase =
    $json.interpretacionAgenda?.fecha_detectada ||
    "";

  if (
    !fechaBase &&
    $json.estadoAgenda?.start_time
  ) {
    fechaBase = DateTime.fromISO(
      $json.estadoAgenda.start_time
    )
      .setZone(tz)
      .toISODate();
  }

  if (!fechaBase) {
    try {
      const opciones = JSON.parse(
        $json.estadoAgenda?.opciones_json ||
        "[]"
      );

      const primera =
        Array.isArray(opciones)
          ? opciones[0]
          : null;

      fechaBase =
        primera?.fecha ||
        String(
          primera?.inicio || ""
        ).slice(0, 10);
    } catch {}
  }

  fechaBase =
    fechaBase ||
    $now.setZone(tz).toISODate();

  return DateTime.fromISO(
    fechaBase,
    { zone: tz }
  )
    .startOf("day")
    .plus({ days: dias })
    .toISO();
})()
}}

parameters.jsCode:
let solicitud =
  $("Interpretar fecha y hora agenda").first().json;

// Cuando existe una fecha y hora completa, recuperamos también
// la validación de la jornada de atención.
try {
  const solicitudValidada =
    $("Validar horario de atención").first().json;

  if (
    solicitudValidada?.session_key ===
    solicitud?.session_key
  ) {
    solicitud = solicitudValidada;
  }
} catch {
  // En solicitudes sin fecha y hora completa,
  // este nodo puede no haberse ejecutado.
}

let vieneDeHorarioOcupado = false;

try {
  const resultadoDisponibilidad =
    $("Consolidar resultado disponibilidad")
      .first()
      .json;

  vieneDeHorarioOcupado =
    resultadoDisponibilidad
      ?.disponibilidad
      ?.available === false;
} catch {
  // La consulta de disponibilidad no se ejecuta
  // cuando falta una hora o está fuera de la jornada.
}

const vieneDeHorarioNoPermitido =
  solicitud
    ?.validacionHorarioAtencion
    ?.horarioPermitido === false;

const motivoHorarioNoPermitido =
  solicitud
    ?.validacionHorarioAtencion
    ?.motivo || "";

const eventosOcupados = $input
  .all()
  .map((item) => item.json)
  .filter((evento) => {
    const eventoConHora =
      evento?.start?.dateTime &&
      evento?.end?.dateTime;

    const eventoDiaCompleto =
      evento?.start?.date &&
      evento?.end?.date;

    return eventoConHora || eventoDiaCompleto;
  });

return [
  {
    json: {
      ...solicitud,

      eventosOcupados,
      totalEventosOcupados:
        eventosOcupados.length,

      vieneDeHorarioOcupado,
      vieneDeHorarioNoPermitido,
      motivoHorarioNoPermitido
    }
  }
];

const config = $json.agendaConfig || {};
const estadoPrevio = $json.estadoAgenda || {};

const zonaHoraria =
  config.zona_horaria || "America/Santiago";

const duracionMinutos =
  Number(config.duracion_minutos) || 30;

const intervaloInicioMinutos =
  Number(config.intervalo_inicio_minutos) || 30;

const diasABuscar =
  Number(config.dias_a_buscar) || 7;

const cantidadAlternativas =
  Number(config.cantidad_alternativas) || 3;

const horariosPorDia =
  config.horarios_por_dia || {};

const fechasBloqueadas = Array.isArray(
  config.fechas_bloqueadas
)
  ? config.fechas_bloqueadas
  : [];

const eventosOcupadosEntrada = Array.isArray(
  $json.eventosOcupados
)
  ? $json.eventosOcupados
  : [];

const normalizarTexto = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const textoCliente = normalizarTexto($json.message);

const nombresDias = [
  "domingo",
  "lunes",
  "martes",
  "miercoles",
  "jueves",
  "viernes",
  "sabado"
];

const nombresDiasPresentacion = [
  "domingo",
  "lunes",
  "martes",
  "miércoles",
  "jueves",
  "viernes",
  "sábado"
];

const nombresMeses = [
  "enero",
  "febrero",
  "marzo",
  "abril",
  "mayo",
  "junio",
  "julio",
  "agosto",
  "septiembre",
  "octubre",
  "noviembre",
  "diciembre"
];

const meses = {
  enero: 1,
  febrero: 2,
  marzo: 3,
  abril: 4,
  mayo: 5,
  junio: 6,
  julio: 7,
  agosto: 8,
  septiembre: 9,
  setiembre: 9,
  octubre: 10,
  noviembre: 11,
  diciembre: 12
};

const diasSemanaTexto = {
  domingo: 0,
  lunes: 1,
  martes: 2,
  miercoles: 3,
  jueves: 4,
  viernes: 5,
  sabado: 6
};

function getLocalParts(date) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: zonaHoraria,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).formatToParts(date);

  const resultado = {};

  for (const part of parts) {
    resultado[part.type] = part.value;
  }

  return {
    year: Number(resultado.year),
    month: Number(resultado.month),
    day: Number(resultado.day),
    hour: Number(resultado.hour),
    minute: Number(resultado.minute),
    date:
      `${resultado.year}-${resultado.month}-${resultado.day}`
  };
}

function addDaysToLocalDate(dateString, days) {
  const [year, month, day] =
    dateString.split("-").map(Number);

  const date = new Date(
    Date.UTC(year, month - 1, day + days, 12, 0, 0)
  );

  return getLocalParts(date).date;
}

function getDayOfWeek(dateString) {
  const [year, month, day] =
    dateString.split("-").map(Number);

  return new Date(
    Date.UTC(year, month - 1, day)
  ).getUTCDay();
}

function horaAMinutos(horaTexto) {
  const [hora, minuto] =
    String(horaTexto || "00:00")
      .split(":")
      .map(Number);

  return hora * 60 + minuto;
}

function minutosAHora(minutos) {
  const hora = String(
    Math.floor(minutos / 60)
  ).padStart(2, "0");

  const minuto = String(
    minutos % 60
  ).padStart(2, "0");

  return `${hora}:${minuto}`;
}

function parseEvento(evento) {
  if (evento.start?.date) {
    return {
      fecha: evento.start.date,
      inicioMinutos: 0,
      finMinutos: 24 * 60
    };
  }

  const inicio = evento.start?.dateTime;
  const fin = evento.end?.dateTime;

  if (!inicio || !fin) {
    return null;
  }

  const inicioLocal = getLocalParts(new Date(inicio));
  const finLocal = getLocalParts(new Date(fin));

  return {
    fecha: inicioLocal.date,
    inicioMinutos:
      inicioLocal.hour * 60 + inicioLocal.minute,
    finMinutos:
      finLocal.hour * 60 + finLocal.minute
  };
}

function estaOcupado(
  fecha,
  inicioMinutos,
  finMinutos,
  eventos
) {
  return eventos.some((evento) => {
    if (evento.fecha !== fecha) {
      return false;
    }

    return (
      inicioMinutos < evento.finMinutos &&
      finMinutos > evento.inicioMinutos
    );
  });
}

function etiquetaFechaHora(fecha, hora) {
  const [year, month, day] =
    fecha.split("-").map(Number);

  const diaSemana = getDayOfWeek(fecha);

  return (
    `${nombresDiasPresentacion[diaSemana]} ` +
    `${day} de ${nombresMeses[month - 1]} ` +
    `a las ${hora}`
  );
}

function leerOpcionesPrevias() {
  const valor = estadoPrevio.opciones_json;

  if (Array.isArray(valor)) {
    return valor;
  }

  if (!valor) {
    return [];
  }

  try {
    const opciones = JSON.parse(valor);
    return Array.isArray(opciones) ? opciones : [];
  } catch {
    return [];
  }
}

function obtenerFechaOpcion(opcion) {
  if (opcion?.fecha) {
    return String(opcion.fecha);
  }

  const inicio = String(opcion?.inicio || "");
  const coincidencia = inicio.match(
    /^(\d{4}-\d{2}-\d{2})/
  );

  return coincidencia?.[1] || "";
}

function obtenerMinutoInicioOpcion(opcion) {
  if (opcion?.hora) {
    return horaAMinutos(opcion.hora);
  }

  const inicio = String(opcion?.inicio || "");
  const coincidencia = inicio.match(
    /T(\d{2}):(\d{2})/
  );

  if (!coincidencia) {
    return null;
  }

  return (
    Number(coincidencia[1]) * 60 +
    Number(coincidencia[2])
  );
}

const opcionesPrevias = leerOpcionesPrevias();

const prefiereMasTarde =
  /\bmas tarde\b/.test(textoCliente) ||
  /\buna hora posterior\b/.test(textoCliente) ||
  /\bhorarios posteriores\b/.test(textoCliente);

const prefiereMasTemprano =
  /\bmas temprano\b/.test(textoCliente) ||
  /\buna hora anterior\b/.test(textoCliente) ||
  /\bhorarios anteriores\b/.test(textoCliente);

const prefiereTarde =
  !prefiereMasTarde &&
  (
    /\bpor la tarde\b/.test(textoCliente) ||
    /\ben la tarde\b/.test(textoCliente) ||
    /\bde la tarde\b/.test(textoCliente) ||
    /^tarde$/.test(textoCliente)
  );

const prefiereManana =
  !prefiereMasTemprano &&
  (
    /\ben la manana\b/.test(textoCliente) ||
    /\bpor la manana\b/.test(textoCliente) ||
    /\bde la manana\b/.test(textoCliente) ||
    /\btemprano\b/.test(textoCliente)
  );

const rechazaAlternativas =
  /\bno me sirven\b/.test(textoCliente) ||
  /\bno me sirve\b/.test(textoCliente) ||
  /\bno me acomoda\b/.test(textoCliente) ||
  /\bno me acomodan\b/.test(textoCliente) ||
  /\botra hora\b/.test(textoCliente) ||
  /\botras horas\b/.test(textoCliente) ||
  /\botro horario\b/.test(textoCliente) ||
  /\botros horarios\b/.test(textoCliente) ||
  /\botras opciones\b/.test(textoCliente) ||
  /\bdame otras\b/.test(textoCliente) ||
  prefiereMasTarde ||
  prefiereMasTemprano;

function extraerFechaIndicadaPorCliente() {
  const ahoraLocal = getLocalParts(new Date());

  const diceMananaComoDia =
    /\bmanana\b/.test(textoCliente) &&
    !/\ben la manana\b/.test(textoCliente) &&
    !/\bpor la manana\b/.test(textoCliente) &&
    !/\bde la manana\b/.test(textoCliente);

  if (/\bhoy\b/.test(textoCliente)) {
    return ahoraLocal.date;
  }

  if (/\bpasado manana\b/.test(textoCliente)) {
    return addDaysToLocalDate(
      ahoraLocal.date,
      2
    );
  }

  if (diceMananaComoDia) {
    return addDaysToLocalDate(
      ahoraLocal.date,
      1
    );
  }

  const fechaExplicita = textoCliente.match(
    /\b(\d{1,2})\s+de\s+([a-z]+)(?:\s+de\s+(\d{4}))?\b/
  );

  if (fechaExplicita) {
    const dia = String(
      Number(fechaExplicita[1])
    ).padStart(2, "0");

    const mesNumero =
      meses[fechaExplicita[2]];

    const anio = fechaExplicita[3]
      ? Number(fechaExplicita[3])
      : ahoraLocal.year;

    if (mesNumero) {
      const mes = String(
        mesNumero
      ).padStart(2, "0");

      return `${anio}-${mes}-${dia}`;
    }
  }

  for (
    const [diaTexto, diaNumero]
    of Object.entries(diasSemanaTexto)
  ) {
    if (
      new RegExp(`\\b${diaTexto}\\b`)
        .test(textoCliente)
    ) {
      for (let i = 0; i < diasABuscar; i++) {
        const fecha = addDaysToLocalDate(
          ahoraLocal.date,
          i
        );

        if (
          getDayOfWeek(fecha) === diaNumero
        ) {
          return fecha;
        }
      }
    }
  }

  return null;
}

const fechaIndicadaPorCliente =
  extraerFechaIndicadaPorCliente();

const ultimaOpcionPrevia =
  opcionesPrevias.length > 0
    ? opcionesPrevias[opcionesPrevias.length - 1]
    : null;

const fechaUltimaOpcion =
  obtenerFechaOpcion(ultimaOpcionPrevia);

const fechaInterpretada = String(
  $json.interpretacionAgenda?.fecha_detectada || ""
);

const horaInterpretada = String(
  $json.interpretacionAgenda?.hora_detectada || ""
);

const minutoSolicitado =
  /^\d{2}:\d{2}$/.test(horaInterpretada)
    ? horaAMinutos(horaInterpretada)
    : null;

const vieneDeHorarioOcupado =
  $json.vieneDeHorarioOcupado === true;

const vieneDeHorarioNoPermitido =
  $json.vieneDeHorarioNoPermitido === true;

let fechaPreferida =
  fechaIndicadaPorCliente;

if (
  !fechaPreferida &&
  fechaUltimaOpcion &&
  (
    prefiereMasTarde ||
    prefiereMasTemprano ||
    rechazaAlternativas ||
    estadoPrevio.estado_agenda ===
      "esperando_seleccion_horario"
  )
) {
  fechaPreferida = fechaUltimaOpcion;
}

if (
  !fechaPreferida &&
  (
    vieneDeHorarioOcupado ||
    vieneDeHorarioNoPermitido
  ) &&
  fechaInterpretada
) {
  fechaPreferida = fechaInterpretada;
}

const opcionesPreviasDeFecha =
  fechaPreferida
    ? opcionesPrevias.filter(
        (opcion) =>
          obtenerFechaOpcion(opcion) ===
          fechaPreferida
      )
    : [];

const minutosOpcionesPrevias =
  opcionesPreviasDeFecha
    .map(obtenerMinutoInicioOpcion)
    .filter(Number.isFinite)
    .sort((a, b) => a - b);

let minutoMinimoRelativo = null;
let minutoMaximoRelativo = null;

if (
  prefiereMasTarde &&
  minutosOpcionesPrevias.length > 0
) {
  minutoMinimoRelativo =
    minutosOpcionesPrevias[
      minutosOpcionesPrevias.length - 1
    ] + intervaloInicioMinutos;
}

if (
  prefiereMasTemprano &&
  minutosOpcionesPrevias.length > 0
) {
  minutoMaximoRelativo =
    minutosOpcionesPrevias[0];
}

const debeRespetarHoraSolicitada =
  Number.isFinite(minutoSolicitado) &&
  !prefiereMasTarde &&
  !prefiereMasTemprano &&
  (
    vieneDeHorarioOcupado ||
    vieneDeHorarioNoPermitido
  );

function siguienteInicioValido(
  minutoReferencia,
  minutoApertura
) {
  if (minutoReferencia <= minutoApertura) {
    return minutoApertura;
  }

  const diferencia =
    minutoReferencia - minutoApertura;

  return (
    minutoApertura +
    Math.ceil(
      diferencia / intervaloInicioMinutos
    ) * intervaloInicioMinutos
  );
}

const ahoraLocal =
  getLocalParts(new Date());

const minutoActual =
  ahoraLocal.hour * 60 +
  ahoraLocal.minute;

const eventosOcupados =
  eventosOcupadosEntrada
    .map(parseEvento)
    .filter(Boolean);

const opciones = [];

const fechasCandidatas = [];

const fechaBaseBusqueda =
  fechaPreferida || ahoraLocal.date;

for (let i = 0; i < diasABuscar; i++) {
  fechasCandidatas.push(
    addDaysToLocalDate(
      fechaBaseBusqueda,
      i
    )
  );
}

for (const fecha of fechasCandidatas) {
  if (
    opciones.length >= cantidadAlternativas
  ) {
    break;
  }

  if (fechasBloqueadas.includes(fecha)) {
    continue;
  }

  const diaSemana =
    getDayOfWeek(fecha);

  const nombreDia =
    nombresDias[diaSemana];

  const horario =
    horariosPorDia[nombreDia];

  if (!horario) {
    continue;
  }

  let inicioBusqueda =
    horaAMinutos(horario.apertura);

  let cierreBusqueda =
    horaAMinutos(horario.cierre);

  if (
    fecha === fechaPreferida &&
    debeRespetarHoraSolicitada
  ) {
    const aperturaMinutos =
      horaAMinutos(horario.apertura);

    const inicioValidoMasCercano =
      siguienteInicioValido(
        minutoSolicitado,
        aperturaMinutos
      );

    inicioBusqueda = Math.max(
      inicioBusqueda,
      inicioValidoMasCercano
    );
  }

  if (prefiereTarde) {
    inicioBusqueda = Math.max(
      inicioBusqueda,
      14 * 60
    );
  }

  if (prefiereManana) {
    cierreBusqueda = Math.min(
      cierreBusqueda,
      12 * 60
    );
  }

  if (
    fecha === fechaPreferida &&
    minutoMinimoRelativo !== null
  ) {
    inicioBusqueda = Math.max(
      inicioBusqueda,
      minutoMinimoRelativo
    );
  }

  if (
    fecha === fechaPreferida &&
    minutoMaximoRelativo !== null
  ) {
    cierreBusqueda = Math.min(
      cierreBusqueda,
      minutoMaximoRelativo
    );
  }

  for (
    let inicio = inicioBusqueda;
    inicio + duracionMinutos <= cierreBusqueda;
    inicio += intervaloInicioMinutos
  ) {
    const fin =
      inicio + duracionMinutos;

    if (
      fecha === ahoraLocal.date &&
      inicio <= minutoActual
    ) {
      continue;
    }

    if (
      estaOcupado(
        fecha,
        inicio,
        fin,
        eventosOcupados
      )
    ) {
      continue;
    }

    const horaInicio =
      minutosAHora(inicio);

    const horaFin =
      minutosAHora(fin);

    opciones.push({
      numero: opciones.length + 1,
      fecha,
      hora: horaInicio,
      inicio:
        `${fecha}T${horaInicio}:00`,
      fin:
        `${fecha}T${horaFin}:00`,
      texto:
        etiquetaFechaHora(
          fecha,
          horaInicio
        )
    });

    if (
      opciones.length >= cantidadAlternativas
    ) {
      break;
    }
  }
}

const datosFaltantes =
  Array.isArray($json.datosFaltantes)
    ? $json.datosFaltantes
    : [];

let mensajeOpcionesAgenda = "";

if (opciones.length > 0) {
  let introduccion =
    "Tengo estas alternativas reales disponibles:";

  if ($json.vieneDeHorarioOcupado) {
    introduccion =
      "Ese horario no está disponible. " +
      "Tengo estas alternativas reales:";
  } else if (
    prefiereMasTarde ||
    prefiereMasTemprano ||
    rechazaAlternativas
  ) {
    introduccion =
      "Claro, revisé nuevas alternativas disponibles:";
  }

  const lista = opciones
    .map(
      (opcion) =>
        `${opcion.numero}. ${opcion.texto}`
    )
    .join("\n");

  if (datosFaltantes.length > 0) {
    mensajeOpcionesAgenda =
      `${introduccion}\n\n${lista}` +
      "\n\nPara confirmar necesito también: " +
      datosFaltantes.join(", ") +
      ". Puedes responder con el número de la opción " +
      "junto con esos datos.";
  } else {
    mensajeOpcionesAgenda =
      `${introduccion}\n\n${lista}` +
      "\n\n¿Cuál opción prefieres? " +
      "Puedes responder con el número.";
  }
} else {
  mensajeOpcionesAgenda =
    "No encontré horarios disponibles dentro de la " +
    "configuración actual de la clínica. " +
    "Puedes indicarme otra fecha o preferencia horaria.";
}

return {
  json: {
    ...$json,

    opcionesAgenda: opciones,
    totalOpciones: opciones.length,

    preferenciasAgenda: {
      fechaPreferida,
      fechaIndicadaPorCliente,
      prefiereManana,
      prefiereTarde,
      prefiereMasTemprano,
      prefiereMasTarde,
      rechazaAlternativas,
      minutoMinimoRelativo,
      minutoMaximoRelativo
    },

    mensajeOpcionesAgenda,

    estadoAgenda: {
      ...estadoPrevio,

      estado_agenda:
        opciones.length > 0
          ? "esperando_seleccion_horario"
          : "sin_horarios_disponibles",

      start_time: "",

      opciones_json:
        JSON.stringify(opciones)
    }
  }
};

const estadoPrevio = $json.estadoAgenda || {};

return {
  json: {
    ...$json,

    estadoAgenda: {
      ...estadoPrevio,
      estado_agenda: "esperando_datos_minimos",
      start_time:
        $json.startTime ||
        estadoPrevio.start_time ||
        "",
      opciones_json: "[]"
    }
  }
};

const solicitud =
  $("Tiene datos mínimos para confirmar").first().json;

const eventoCreado = $json || {};

const zonaHoraria =
  solicitud.agendaConfig?.zona_horaria ||
  "America/Santiago";

const inicio = new Date(solicitud.startTime);

const fechaHoraTexto = new Intl.DateTimeFormat(
  "es-CL",
  {
    timeZone: zonaHoraria,
    dateStyle: "full",
    timeStyle: "short"
  }
).format(inicio);

return {
  json: {
    ...solicitud,

    eventoCreado: {
      id: eventoCreado.id || "",
      status: eventoCreado.status || "",
      htmlLink: eventoCreado.htmlLink || ""
    },

    fechaHoraTexto,

    estadoAgenda: {
      ...solicitud.estadoAgenda,
      estado_agenda: "confirmada",
      start_time: solicitud.startTime,
      opciones_json: "[]"
    }
  }
};

const estadoPrevio =
  $json.estadoAgenda || {};

return {
  json: {
    ...$json,

    estadoAgenda: {
      ...estadoPrevio,

      estado_agenda:
        "esperando_horario_futuro",

      start_time:
        "",

      fecha_pendiente:
        "",

      hora_pendiente:
        "",

      opciones_json:
        "[]"
    },

    mensajeFechaPasada:
      "La fecha u hora indicada ya pasó. Por favor, indícame una fecha y hora futura para revisar su disponibilidad."
  }
};

const mensaje = String($json.message || "").trim();
const estadoPrevio = $json.estadoAgenda || {};

const limpiarNombre = (valor) =>
  String(valor || "")
    .replace(/\s+/g, " ")
    .replace(/[.,;:]+$/g, "")
    .trim();

const valorEstadoValido = (valor) => {
  const texto = String(valor || "").trim();

  // Evita reutilizar expresiones que hayan quedado
  // guardadas accidentalmente como texto literal.
  if (
    !texto ||
    (texto.includes("{{") && texto.includes("}}"))
  ) {
    return "";
  }

  return texto;
};

const extraerPrimeraCoincidencia = (patrones) => {
  for (const patron of patrones) {
    const coincidencia = mensaje.match(patron);

    if (coincidencia?.[1]) {
      return limpiarNombre(coincidencia[1]);
    }
  }

  return "";
};

// Palabras permitidas para nombres y tipos de mascota.
// Permite expresiones como:
// perro, gata, conejo, loro, tortuga, dragón barbudo, etc.
const palabraNombre =
  "[A-Za-zÁÉÍÓÚÜÑáéíóúüñ'-]+";

const tipoMascota =
  `(?:mascota|${palabraNombre}(?:\\s+${palabraNombre}){0,2})`;

// --------------------------------------------------
// 1. Extraer nombre del tutor
// --------------------------------------------------

const nombreTutorDetectado = extraerPrimeraCoincidencia([
  new RegExp(
    `\\bmi nombre es\\s+(.+?)(?=\\s+(?:y\\s+)?(?:mi\\s+${tipoMascota}\\s+se llama|mi\\s+n[uú]mero|mi\\s+tel[eé]fono|tel[eé]fono|celular)\\b|[.,;]|$)`,
    "i"
  ),

  new RegExp(
    `\\bme llamo\\s+(.+?)(?=\\s+(?:y\\s+)?(?:mi\\s+${tipoMascota}\\s+se llama|mi\\s+n[uú]mero|mi\\s+tel[eé]fono|tel[eé]fono|celular)\\b|[.,;]|$)`,
    "i"
  ),

  new RegExp(
    `\\bsoy\\s+(.+?)(?=\\s+(?:y\\s+)?(?:mi\\s+${tipoMascota}\\s+se llama|mi\\s+n[uú]mero|mi\\s+tel[eé]fono|tel[eé]fono|celular)\\b|[.,;]|$)`,
    "i"
  ),

  /\btutor(?:a)?\s*:\s*([^,.;]+)/i
]);

// --------------------------------------------------
// 2. Extraer nombre de la mascota
// --------------------------------------------------

let nombreMascotaDetectado =
  extraerPrimeraCoincidencia([
    new RegExp(
      `\\bmi\\s+${tipoMascota}\\s+se llama\\s+(.+?)(?=\\s+(?:y\\s+)?(?:mi nombre|me llamo|soy|mi n[uú]mero|n[uú]mero|mi tel[eé]fono|tel[eé]fono|celular)\\b|[.,;]|$)`,
      "i"
    ),

    new RegExp(
      `\\b(?:la|el)\\s+${tipoMascota}\\s+se llama\\s+(.+?)(?=\\s+(?:y\\s+)?(?:mi nombre|me llamo|soy|mi n[uú]mero|n[uú]mero|mi tel[eé]fono|tel[eé]fono|celular)\\b|[.,;]|$)`,
      "i"
    ),

    /\bmascota\s*:\s*([^,.;]+)/i
  ]);

// Compatibilidad con frases sin "se llama":
//
// "Mi tortuga Lola necesita una consulta."
// "Mi conejo Pelusa tiene una molestia."
// "Mi dragón barbudo Rocco requiere atención."
if (!nombreMascotaDetectado) {
  const coincidenciaMascota = mensaje.match(
    new RegExp(
      `\\bmi\\s+${tipoMascota}\\s+(${palabraNombre})(?=\\s+(?:necesita|tiene|est[aá]|presenta|requiere|quiere|debe)\\b|[.,;]|$)`,
      "i"
    )
  );

  if (coincidenciaMascota?.[1]) {
    nombreMascotaDetectado =
      limpiarNombre(coincidenciaMascota[1]);
  }
}

// --------------------------------------------------
// 3. Extraer teléfono chileno
// --------------------------------------------------

let telefonoDetectado = "";

const coincidenciaTelefono = mensaje.match(
  /(?:\+?56[\s.-]*)?(9(?:[\s.-]*\d){8})\b/
);

if (coincidenciaTelefono?.[1]) {
  const numero =
    coincidenciaTelefono[1].replace(/\D/g, "");

  telefonoDetectado = `+56${numero}`;
}

// --------------------------------------------------
// 4. Recuperar información previa válida
// --------------------------------------------------

const nombreTutorPrevio = valorEstadoValido(
  estadoPrevio.nombre_tutor
);

const nombreMascotaPrevio = valorEstadoValido(
  estadoPrevio.nombre_mascota
);

const telefonoPrevio = valorEstadoValido(
  estadoPrevio.telefono
);

// --------------------------------------------------
// 5. Consolidar el estado de la agenda
// --------------------------------------------------

const estadoAgenda = {
  ...estadoPrevio,

  nombre_tutor:
    nombreTutorDetectado ||
    nombreTutorPrevio ||
    "",

  nombre_mascota:
    nombreMascotaDetectado ||
    nombreMascotaPrevio ||
    "",

  telefono:
    telefonoDetectado ||
    telefonoPrevio ||
    ""
};

// --------------------------------------------------
// 6. Determinar datos faltantes
// --------------------------------------------------

const datosFaltantes = [];

if (!estadoAgenda.nombre_tutor) {
  datosFaltantes.push("nombre del tutor");
}

if (!estadoAgenda.nombre_mascota) {
  datosFaltantes.push("nombre de la mascota");
}

if (!estadoAgenda.telefono) {
  datosFaltantes.push("teléfono de contacto");
}

// --------------------------------------------------
// 7. Entregar resultado
// --------------------------------------------------

return {
  json: {
    ...$json,
    estadoAgenda,

    datosDetectados: {
      nombre_tutor: nombreTutorDetectado,
      nombre_mascota: nombreMascotaDetectado,
      telefono: telefonoDetectado
    },

    datosFaltantes,
    tieneDatosMinimos:
      datosFaltantes.length === 0
  }
};

const config = $json.agendaConfig || {};

const zonaHoraria =
  config.zona_horaria || "America/Santiago";

const duracionMinutos =
  Number(config.duracion_minutos) || 30;

const intervaloInicioMinutos =
  Number(config.intervalo_inicio_minutos) || 30;

const horariosPorDia =
  config.horarios_por_dia || {};

const fechasBloqueadas = Array.isArray(
  config.fechas_bloqueadas
)
  ? config.fechas_bloqueadas
      .map((fecha) => String(fecha || "").trim())
      .filter(Boolean)
  : [];

const startTime =
  String($json.startTime || "").trim();

const endTime =
  String($json.endTime || "").trim();

const nombresDias = [
  "domingo",
  "lunes",
  "martes",
  "miercoles",
  "jueves",
  "viernes",
  "sabado"
];

function obtenerPartesLocales(isoDateTime) {
  const fecha = new Date(isoDateTime);

  if (Number.isNaN(fecha.getTime())) {
    return null;
  }

  const partes = new Intl.DateTimeFormat(
    "en-CA",
    {
      timeZone: zonaHoraria,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }
  ).formatToParts(fecha);

  const resultado = {};

  for (const parte of partes) {
    resultado[parte.type] = parte.value;
  }

  const fechaLocal =
    `${resultado.year}-${resultado.month}-${resultado.day}`;

  return {
    fecha: fechaLocal,
    hora: Number(resultado.hour),
    minuto: Number(resultado.minute),
    minutosTotales:
      Number(resultado.hour) * 60 +
      Number(resultado.minute)
  };
}

function obtenerDiaSemana(fechaLocal) {
  const [anio, mes, dia] =
    fechaLocal.split("-").map(Number);

  return new Date(
    Date.UTC(anio, mes - 1, dia)
  ).getUTCDay();
}

function horaAMinutos(horaTexto) {
  const [hora, minuto] =
    String(horaTexto || "00:00")
      .split(":")
      .map(Number);

  return hora * 60 + minuto;
}

let horarioPermitido = false;
let motivoHorarioNoPermitido = "";

const inicioLocal =
  obtenerPartesLocales(startTime);

const finLocal =
  obtenerPartesLocales(endTime);

if (!inicioLocal || !finLocal) {
  motivoHorarioNoPermitido =
    "fecha_hora_invalida";
} else if (
  inicioLocal.fecha !== finLocal.fecha
) {
  motivoHorarioNoPermitido =
    "la_cita_cruza_de_dia";
} else if (
  fechasBloqueadas.includes(inicioLocal.fecha)
) {
  motivoHorarioNoPermitido =
    "fecha_bloqueada";
} else {
  const numeroDia =
    obtenerDiaSemana(inicioLocal.fecha);

  const nombreDia =
    nombresDias[numeroDia];

  const horarioDia =
    horariosPorDia[nombreDia];

  if (!horarioDia) {
    motivoHorarioNoPermitido =
      "dia_sin_atencion";
  } else {
    const aperturaMinutos =
      horaAMinutos(horarioDia.apertura);

    const cierreMinutos =
      horaAMinutos(horarioDia.cierre);

    const inicioMinutos =
      inicioLocal.minutosTotales;

    const finMinutos =
      finLocal.minutosTotales;

    const duracionReal =
      finMinutos - inicioMinutos;

    const coincideIntervalo =
      (
        inicioMinutos -
        aperturaMinutos
      ) % intervaloInicioMinutos === 0;

    if (inicioMinutos < aperturaMinutos) {
      motivoHorarioNoPermitido =
        "antes_de_la_apertura";
    } else if (finMinutos > cierreMinutos) {
      motivoHorarioNoPermitido =
        "despues_del_cierre";
    } else if (
      duracionReal !== duracionMinutos
    ) {
      motivoHorarioNoPermitido =
        "duracion_no_permitida";
    } else if (!coincideIntervalo) {
      motivoHorarioNoPermitido =
        "inicio_fuera_del_intervalo_configurado";
    } else {
      horarioPermitido = true;
    }
  }
}

return {
  json: {
    ...$json,

    validacionHorarioAtencion: {
      horarioPermitido,

      motivo:
        horarioPermitido
          ? "horario_valido"
          : motivoHorarioNoPermitido,

      fecha:
        inicioLocal?.fecha || "",

      horaInicio:
        inicioLocal
          ? `${String(inicioLocal.hora).padStart(2, "0")}:${String(inicioLocal.minuto).padStart(2, "0")}`
          : "",

      horaFin:
        finLocal
          ? `${String(finLocal.hora).padStart(2, "0")}:${String(finLocal.minuto).padStart(2, "0")}`
          : "",

      fechaBloqueada:
        Boolean(
          inicioLocal &&
          fechasBloqueadas.includes(
            inicioLocal.fecha
          )
        )
    }
  }
};

const opciones = Array.isArray($json.opcionesAgenda)
  ? $json.opcionesAgenda
  : [];

const config = $json.agendaConfig || {};

const validacion =
  $json.validacionHorarioAtencion || {};

const motivo = String(
  $json.motivoHorarioNoPermitido ||
  validacion.motivo ||
  ""
);

const fechaSolicitada = String(
  validacion.fecha ||
  $json.interpretacionAgenda?.fecha_detectada ||
  ""
);

const datosFaltantes = Array.isArray(
  $json.datosFaltantes
)
  ? $json.datosFaltantes
  : [];

const nombresDiasPresentacion = [
  "domingo",
  "lunes",
  "martes",
  "miércoles",
  "jueves",
  "viernes",
  "sábado"
];

const nombresDiasConfiguracion = [
  "domingo",
  "lunes",
  "martes",
  "miercoles",
  "jueves",
  "viernes",
  "sabado"
];

const nombresMeses = [
  "enero",
  "febrero",
  "marzo",
  "abril",
  "mayo",
  "junio",
  "julio",
  "agosto",
  "septiembre",
  "octubre",
  "noviembre",
  "diciembre"
];

function obtenerPartesFecha(fecha) {
  const [anio, mes, dia] =
    String(fecha || "")
      .split("-")
      .map(Number);

  if (!anio || !mes || !dia) {
    return null;
  }

  const numeroDia = new Date(
    Date.UTC(anio, mes - 1, dia)
  ).getUTCDay();

  return {
    anio,
    mes,
    dia,
    numeroDia,
    nombreDia:
      nombresDiasPresentacion[numeroDia],
    nombreDiaConfiguracion:
      nombresDiasConfiguracion[numeroDia],
    nombreMes:
      nombresMeses[mes - 1]
  };
}

function presentarFecha(fecha) {
  const partes = obtenerPartesFecha(fecha);

  if (!partes) {
    return "la fecha solicitada";
  }

  return (
    `${partes.nombreDia} ` +
    `${partes.dia} de ${partes.nombreMes}`
  );
}

function obtenerHorarioSolicitado() {
  const partes =
    obtenerPartesFecha(fechaSolicitada);

  if (!partes) {
    return null;
  }

  const horario =
    config.horarios_por_dia?.[
      partes.nombreDiaConfiguracion
    ];

  if (!horario) {
    return {
      nombreDia: partes.nombreDia,
      apertura: "",
      cierre: ""
    };
  }

  return {
    nombreDia: partes.nombreDia,
    apertura:
      String(horario.apertura || ""),
    cierre:
      String(horario.cierre || "")
  };
}

const horarioSolicitado =
  obtenerHorarioSolicitado();

let mensajeOpcionesAgenda =
  String(
    $json.mensajeOpcionesAgenda || ""
  );

if (
  $json.vieneDeHorarioNoPermitido === true &&
  opciones.length > 0
) {
  let explicacion =
    "El horario solicitado no está disponible dentro de la jornada configurada.";

  if (
    motivo === "despues_del_cierre" &&
    horarioSolicitado?.cierre
  ) {
    explicacion =
      `El horario solicitado es posterior al cierre. ` +
      `Los ${horarioSolicitado.nombreDia}, ` +
      `la clínica atiende de ` +
      `${horarioSolicitado.apertura} a ` +
      `${horarioSolicitado.cierre}.`;
  } else if (
    motivo === "antes_de_la_apertura" &&
    horarioSolicitado?.apertura
  ) {
    explicacion =
      `El horario solicitado es anterior a la apertura. ` +
      `Los ${horarioSolicitado.nombreDia}, ` +
      `la clínica atiende de ` +
      `${horarioSolicitado.apertura} a ` +
      `${horarioSolicitado.cierre}.`;
  } else if (
    motivo === "dia_sin_atencion"
  ) {
    explicacion =
      `La clínica no tiene atención configurada para ` +
      `${presentarFecha(fechaSolicitada)}.`;
  } else if (
    motivo === "fecha_bloqueada"
  ) {
    explicacion =
      `${presentarFecha(fechaSolicitada)} ` +
      `no está disponible para agendamiento, ` +
      `porque la clínica tiene esa fecha bloqueada.`;
  } else if (
    motivo ===
    "inicio_fuera_del_intervalo_configurado"
  ) {
    explicacion =
      `Ese horario no coincide con los intervalos de inicio ` +
      `configurados para las consultas.`;
  } else if (
    motivo === "duracion_no_permitida"
  ) {
    explicacion =
      "La duración solicitada no coincide con la duración configurada para este servicio.";
  } else if (
    motivo === "la_cita_cruza_de_dia"
  ) {
    explicacion =
      "La cita solicitada no puede extenderse hasta el día siguiente.";
  } else if (
    motivo === "fecha_hora_invalida"
  ) {
    explicacion =
      "No pude interpretar correctamente la fecha y la hora solicitadas.";
  }

  const lista = opciones
    .map(
      (opcion) =>
        `${opcion.numero}. ${opcion.texto}`
    )
    .join("\n");

  if (datosFaltantes.length > 0) {
    mensajeOpcionesAgenda =
      `${explicacion}\n\n` +
      `Estas son algunas opciones disponibles:\n\n` +
      `${lista}\n\n` +
      `Para confirmar necesito también: ` +
      `${datosFaltantes.join(", ")}. ` +
      `Puedes responder con el número de la opción junto con esos datos.`;
  } else {
    mensajeOpcionesAgenda =
      `${explicacion}\n\n` +
      `Estas son algunas opciones disponibles:\n\n` +
      `${lista}\n\n` +
      `¿Cuál opción prefieres? ` +
      `Puedes responder con el número.`;
  }
}

return {
  json: {
    ...$json,
    mensajeOpcionesAgenda
  }
};

