={{
(() => {
  const tz =
    $json.agendaConfig?.zona_horaria ||
    "America/Santiago";

  let fechaBase =
    $json.interpretacionAgenda?.fecha_detectada ||
    "";

  if (
    !fechaBase &&
    $json.estadoAgenda?.start_time
  ) {
    fechaBase = DateTime.fromISO(
      $json.estadoAgenda.start_time
    )
      .setZone(tz)
      .toISODate();
  }

  if (!fechaBase) {
    try {
      const opciones = JSON.parse(
        $json.estadoAgenda?.opciones_json ||
        "[]"
      );

      const primera =
        Array.isArray(opciones)
          ? opciones[0]
          : null;

      fechaBase =
        primera?.fecha ||
        String(
          primera?.inicio || ""
        ).slice(0, 10);
    } catch {}
  }

  fechaBase =
    fechaBase ||
    $now.setZone(tz).toISODate();

  return DateTime.fromISO(
    fechaBase,
    { zone: tz }
  )
    .startOf("day")
    .toISO();
})()
}}

