  if (!fechaBase) {
    try {
      const opciones = JSON.parse(
        $json.estadoAgenda?.opciones_json ||
        "[]"
      );

      const primera =
        Array.isArray(opciones)
          ? opciones[0]
          : null;

      fechaBase =
        primera?.fecha ||
        String(
          primera?.inicio || ""
        ).slice(0, 10);
    } catch {}
  }

  fechaBase =
    fechaBase ||
    $now.setZone(tz).toISODate();

  return DateTime.fromISO(
    fechaBase,
    { zone: tz }
  )
    .startOf("day")
    .plus({ days: dias })
    .toISO();
})()
}}

