parameters.jsCode:
const estadoPrevio =
  $json.estadoAgenda || {};

const horaPendiente =
  String(
    estadoPrevio.hora_pendiente || ""
  ).trim();

const horaLegible =
  horaPendiente || "la hora indicada";

return {
  json: {
    ...$json,

    estadoAgenda: {
      ...estadoPrevio,

      estado_agenda:
        "esperando_fecha_horario",

      start_time:
        "",

      fecha_pendiente:
        "",

      hora_pendiente:
        horaPendiente,

      opciones_json:
        "[]"
    },

    ok:
      true,

    clinic_id:
      estadoPrevio.clinic_id ||
      $json.clinic_id ||
      "",

    session_id:
      estadoPrevio.session_id ||
      $json.session_id ||
      "",

    reply:
      `Ya registré la hora ${horaLegible}. ¿Para qué fecha deseas agendar?`
  }
};

